def feature(s):
    t = s or {}
    v = t.get('volume_per_atom_A3')
    if v is None:
        b = t.get('basic_structure_statistics') or {}
        v = b.get('volume_per_atom_A3')
    if v is None or not isfinite(v) or v <= 0:
        return 0.0
    return log1p(v)

def feature(s):
    t = s or {}
    v = t.get('volume_per_atom_A3')
    if v is None or v <= 0:
        return 0.0
    props = t.get('element_properties') or {}
    total = 0.0
    weight = 0.0
    for el, x in (t.get('composition') or {}).items():
        p = props.get(el) or {}
        r = p.get('covalent_radius_A')
        if x is not None and x > 0 and r is not None and r > 0:
            total += x * r ** 3
            weight += x
    return 4.0 * pi * total / (3.0 * weight * v) if weight > 0 else 0.0

def feature(s):
    t = s or {}
    sites = t.get('sites') or []
    n = len(sites)
    props = t.get('element_properties') or {}
    o = [max(0.0, x.get('occupancy') if x.get('occupancy') is not None else 1.0) for x in sites]
    r = []
    for x in sites:
        a = (props.get(x.get('element')) or {}).get('covalent_radius_A')
        r.append(a if a is not None and a > 0 else 0.0)
    near = [inf] * n
    for b in t.get('neighbors') or []:
        i, j, d = b.get('i'), b.get('j'), b.get('distance_A')
        if i is None or j is None or d is None:
            continue
        if 0 <= i < n and 0 <= j < n and d > 0 and o[j] > 0 and r[i] > 0 and r[j] > 0:
            near[i] = min(near[i], d / (r[i] + r[j]))
    w = sum(o[i] for i in range(n) if isfinite(near[i]))
    return sum(o[i] * near[i] for i in range(n) if isfinite(near[i])) / w if w > 0 else 0.0

