    sites = t.get('sites') or []
    n = len(sites)
    props = t.get('element_properties') or {}
    chi = [(props.get(x.get('element')) or {}).get('eneg') for x in sites]
    o = [max(0.0, x.get('occupancy') if x.get('occupancy') is not None else 1.0) for x in sites]
    mass = sum(o[i] for i in range(n) if chi[i] is not None)
    if mass <= 0:
        return 0.0
    mean = sum(o[i] * chi[i] for i in range(n) if chi[i] is not None) / mass
    var = sum(o[i] * (chi[i] - mean) ** 2 for i in range(n) if chi[i] is not None) / mass
    if var <= 1e-12:
        return 0.0
    neighbors = t.get('neighbors') or []
    near = [inf] * n
    for b in neighbors:
        i, j, d = b.get('i'), b.get('j'), b.get('distance_A')
        if i is not None and j is not None and d is not None and 0 <= i < n and 0 <= j < n and d > 0 and o[j] > 0:
            near[i] = min(near[i], d)
    total = 0.0
    weight = 0.0
    for b in neighbors:
        i, j, d = b.get('i'), b.get('j'), b.get('distance_A')
        if i is None or j is None or d is None:
            continue
        if 0 <= i < n and 0 <= j < n and d > 0 and isfinite(near[i]) and d <= 1.5 * near[i] and chi[i] is not None and chi[j] is not None:
            w = o[i] * o[j] * exp(1.0 - (d / near[i]) ** 6)
            total += w * (chi[i] - chi[j]) ** 2
            weight += w
    return total / (2.0 * var * weight) if weight > 0 else 0.0

