def feature(s):
    t = s or {}
    sites = t.get('sites') or []
    n = len(sites)
    props = t.get('element_properties') or {}
    ion = [(props.get(x.get('element')) or {}).get('first_ionization_energy_eV') for x in sites]
    aff = [(props.get(x.get('element')) or {}).get('electron_affinity_eV') for x in sites]
    o = [max(0.0, x.get('occupancy') if x.get('occupancy') is not None else 1.0) for x in sites]
    neighbors = t.get('neighbors') or []
    near = [inf] * n
    for b in neighbors:
        i, j, d = b.get('i'), b.get('j'), b.get('distance_A')
        if i is not None and j is not None and d is not None and 0 <= i < n and 0 <= j < n and d > 0 and o[j] > 0:
            near[i] = min(near[i], d)
    total = 0.0
    weight = 0.0
    for b in neighbors:
        i, j, d = b.get('i'), b.get('j'), b.get('distance_A')
        if i is None or j is None or d is None:
            continue
        if not (0 <= i < n and 0 <= j < n and d > 0 and isfinite(near[i]) and d <= 1.5 * near[i]):
            continue
        if sites[i].get('element') == sites[j].get('element'):
            continue
        costs = []
        if ion[i] is not None and aff[j] is not None:
            costs.append(ion[i] - aff[j])
        if ion[j] is not None and aff[i] is not None:
            costs.append(ion[j] - aff[i])
        if costs:
            w = o[i] * o[j] * exp(1.0 - (d / near[i]) ** 6)
            total += w * min(costs)
            weight += w
    return total / weight if weight > 0 else 0.0

