def feature(s):
    composition = (s or {}).get('composition') or {}
    values = [x for x in composition.values() if x is not None and x > 0 and isfinite(x)]
    total = sum(values)
    if total <= 0:
        return 0.0
    return -sum((x / total) * log(x / total) for x in values)

